#!/bin/bash
#SBATCH --job-name=rlcs-p63-heterogeneity
#SBATCH --partition=amd-hdr100
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=32
#SBATCH --mem=64G
#SBATCH --time=03:05:00
#SBATCH --output=logs/p63-heterogeneity-%j.log
#SBATCH --error=logs/p63-heterogeneity-%j.log
# Prepared script only. Runtime is generated by tools/estimate_runtime.py.
set -eo pipefail
: "${SLURM_JOB_ID:?Requires a compute allocation}"
: "${TMPDIR:?Node-local scratch is required}"
export TACT="${TACT:-$HOME/workspace/rlcs-replays/tactics}"
cd "$TACT"
export PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 PYTHONPATH="$TACT/src"
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1
export NUMEXPR_NUM_THREADS=1 VECLIB_MAXIMUM_THREADS=1
unset PACK
test -f "$TACT/envs/dlenv.tar.gz" || { echo 'Missing packed project environment'; exit 1; }
source "$TACT/slurm/env.sh"
set -u
P63_MEDIUM="$TACT/artifacts/p3-small-41104745-s42-w6-f10-ksweep/compact"
P63_SMALL="$TACT/artifacts/p3-small-41104720-s42-w6-f10-ksweep/compact"
if [[ -n "${P63_COMPACT:-}" ]]; then
    P63_SOURCE="$P63_COMPACT"
elif [[ -n "${P4_COMPACT:-}" ]]; then
    P63_SOURCE="$P4_COMPACT"
elif [[ -d "$P63_MEDIUM" ]]; then
    P63_SOURCE="$P63_MEDIUM"
else
    P63_SOURCE="$P63_SMALL"
fi
P63_SCRATCH="$TMPDIR/p63-$SLURM_JOB_ID"
P63_ARTIFACTS="$TACT/artifacts/p63-$SLURM_JOB_ID"
mkdir "$P63_SCRATCH" "$P63_ARTIFACTS"
# Verify the installed statsmodels version against the uncompressed model.
python -m tactics_code.pushup_heterogeneity --self-test \
    --artifacts "$P63_ARTIFACTS/self-test" --out "$P63_ARTIFACTS/self-test.json"
# Copy only inventoried development files; never a recursive season tree.
python - "$P63_SOURCE" "$P63_SCRATCH/compact" <<'PY'
from pathlib import Path
import shutil
import sys
from tactics_code.pushup_heterogeneity import guard_path, inventory
source, dest = map(guard_path, sys.argv[1:])
_, audit = inventory(source)
dest.mkdir()
paths = [guard_path(source/'extraction.json')]
for shard in sorted(audit['schema']):
    paths.extend([guard_path(shard), guard_path(Path(shard).with_suffix('.parquet'))])
for path in paths:
    target = guard_path(dest/path.relative_to(source))
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(guard_path(path), target)
PY
printf '%s\n' "$P63_SOURCE" > "$P63_ARTIFACTS/compact_source.txt"
git rev-parse HEAD > "$P63_ARTIFACTS/source_commit.txt"
# Reuse a full development event certificate table when provided; otherwise
# build it using the existing guarded events reader on the allocated machine.
if [[ -n "${P63_REPLAY_EVENTS:-}" ]]; then
    P63_EVENT_ARGS=(--replay-events "$P63_REPLAY_EVENTS")
else
    P63_DATA_ROOT="${P63_DATA_ROOT:-$(dirname "$TACT")/data}"
    P63_EVENT_ARGS=(--data-root "$P63_DATA_ROOT" --state-map "$TACT/state_map_rlcs.json")
fi
python -m tactics_code.pushup_heterogeneity \
    --compact "$P63_SCRATCH/compact" \
    "${P63_EVENT_ARGS[@]}" \
    --scratch "$P63_SCRATCH" --artifacts "$P63_ARTIFACTS" \
    --workers "$SLURM_CPUS_PER_TASK" \
    --out "$TACT/results/pushup_heterogeneity.json"
